    def _stringify(self, transform: StringifyTransform) -> str:
        return self.data

    def get_id(self, version: int) -> str:
        return "L%sE" % self.data
'''
new_cls = '''class ASTNumberLiteral(ASTLiteral):
    def __init__(self, data: str, suffix: str = None) -> None:
        self.data = data
        self.suffix = suffix  # optional user-defined-literal suffix

    def _stringify(self, transform: StringifyTransform) -> str:
        if self.suffix is None:
            return self.data
        return self.data + self.suffix

    def get_id(self, version: int) -> str:
        if self.suffix is None:
            return "L%sE" % self.data
        return "L%s%sE" % (self.data, self.suffix)
'''
